      fontSize: '20px',
      color: '#000',
      fontStyle: 'bold',
      stroke: '#fff',
      strokeThickness: 2
    }).setOrigin(0.5);

    const description = this.add.text(x, y + 10, '능력 없음 · 순수 실력', {
