      color: '#000',
      fontStyle: 'bold',
      stroke: '#fff',
      strokeThickness: 2
    }).setOrigin(0.5);

    const description = this.add.text(x, y + 10, '능력 없음 · 순수 실력', {
      fontSize: '11px',
      color: '#222',
      align: 'center'
    }).setOrigin(0.5);

    const infoBg = this.add.rectangle(x, y + 42, 150, 38, 0xffffff, 0.8);

    const modeInfo = this.add.text(x, y + 34, '🚫 캐릭터 능력 비활성', {
      fontSize: '11px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    const diffInfo = this.add.text(x, y + 50, '📊 EXTREME 기준 난이도', {
      fontSize: '11px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });
    const elements = [button, innerBorder, emojiText, title, description, infoBg, modeInfo, diffInfo];

    elements.forEach(element => {
      if (element !== button) {
        element.setInteractive({ useHandCursor: true });
      }

      element.on('pointerover', () => {
        button.setFillStyle(this.lightenColor(color));
        button.setScale(1.08);
        shadow.setScale(1.08);
        innerBorder.setScale(1.08);
        emojiText.setScale(1.1);
        title.setScale(1.05);
        description.setScale(1.05);
        infoBg.setScale(1.08);
        modeInfo.setScale(1.05);
        diffInfo.setScale(1.05);
      });

      element.on('pointerout', () => {
        button.setFillStyle(color);
