   248→  private lightenColor(color: number): number {
   249→    // 색상을 밝게 만들기
   250→    const r = Math.min(255, ((color >> 16) & 0xFF) + 30);
   251→    const g = Math.min(255, ((color >> 8) & 0xFF) + 30);
   252→    const b = Math.min(255, (color & 0xFF) + 30);
   253→    return (r << 16) | (g << 8) | b;
   254→  }
