     5→export default class LeaderboardScene extends Phaser.Scene {
     6→  private selectedDifficulty: Difficulty = DifficultyEnum.NORMAL;
     7→  private leaderboardData: LeaderboardEntry[] = [];
     8→  private leaderboardTexts: Phaser.GameObjects.Text[] = [];
     9→  private loadingText?: Phaser.GameObjects.Text;
    10→  private errorText?: Phaser.GameObjects.Text;
    11→  private currentRequestId: number = 0; // 요청 추적용 ID
    12→
    13→  constructor() {
    14→    super('LeaderboardScene');
    15→  }
    16→
    17→  init() {
    18→    const last = localStorage.getItem('lastPlayedDifficulty') as Difficulty | null;
