    62→
    63→  private createDifficultyButtons() {
    64→    const difficulties: Difficulty[] = [
    65→      DifficultyEnum.NORMAL,
    66→      DifficultyEnum.HARD,
    67→      DifficultyEnum.EXTREME,
    68→      DifficultyEnum.PHYSICAL
    69→    ];
    70→
    71→    const buttonWidth = 70;
