   116→  private selectDifficulty(difficulty: Difficulty) {
   117→    // 같은 난이도면 무시
   118→    if (this.selectedDifficulty === difficulty) {
   119→      return;
   120→    }
   121→
   122→    this.selectedDifficulty = difficulty;
   123→
   124→    // 모든 버튼 스타일 재설정
   125→    this.children.list.forEach((child) => {
   126→      if (child instanceof Phaser.GameObjects.Rectangle && child.y === 95) {
   127→        const index = Math.round((child.x - 72.5) / 85);
   128→        const difficulties = [DifficultyEnum.NORMAL, DifficultyEnum.HARD, DifficultyEnum.EXTREME, DifficultyEnum.PHYSICAL];
   129→        const isSelected = difficulties[index] === difficulty;
   130→
   131→        child.setFillStyle(isSelected ? 0xffff99 : 0xffffff);
   132→        child.setStrokeStyle(3, isSelected ? 0xff0000 : 0x000000);
   133→      }
   134→    });
