   140→  private async loadLeaderboard() {
   141→    // 요청 ID 증가 (새로운 요청 시작)
   142→    this.currentRequestId++;
   143→    const requestId = this.currentRequestId;
   144→
   145→    // 기존 랭킹 텍스트 제거
   146→    this.leaderboardTexts.forEach(text => text.destroy());
   147→    this.leaderboardTexts = [];
   148→
   149→    if (this.errorText) {
   150→      this.errorText.destroy();
   151→      this.errorText = undefined;
   152→    }
   153→
   154→    // 로딩 표시
   155→    if (!this.loadingText) {
   156→      this.loadingText = this.add.text(200, 300, '로딩 중...', {
   157→        fontSize: '20px',
   158→        color: '#fff',
   159→        stroke: '#000',
   160→        strokeThickness: 3
   161→      }).setOrigin(0.5);
   162→    } else {
   163→      this.loadingText.setVisible(true);
   164→    }
   165→
   166→    try {
   167→      const response = await getLeaderboard(this.selectedDifficulty, 10);
   168→
   169→      // 응답이 도착했을 때 최신 요청인지 확인
   170→      if (requestId !== this.currentRequestId) {
   171→        // 이미 새로운 요청이 시작됨 - 이 응답은 무시
   172→        return;
   173→      }
   174→
   175→      this.leaderboardData = response.leaderboard;
   176→
   177→      if (this.loadingText) {
   178→        this.loadingText.setVisible(false);
   179→      }
   180→
   181→      this.displayLeaderboard();
   182→    } catch (error) {
   183→      // 에러가 발생했을 때도 최신 요청인지 확인
   184→      if (requestId !== this.currentRequestId) {
   185→        // 이미 새로운 요청이 시작됨 - 이 에러는 무시
   186→        return;
   187→      }
   188→
   189→      console.error('Failed to load leaderboard:', error);
   190→
   191→      if (this.loadingText) {
   192→        this.loadingText.setVisible(false);
   193→      }
   194→
   195→      this.errorText = this.add.text(200, 300, '랭킹을 불러올 수 없습니다\n\n나중에 다시 시도해주세요', {
   196→        fontSize: '16px',
   197→        color: '#ff6666',
   198→        stroke: '#000',
   199→        strokeThickness: 3,
   200→        align: 'center'
   201→      }).setOrigin(0.5);
   202→    }
   203→  }
   204→
   205→  private displayLeaderboard() {
   206→    const startY = 150;
   207→    const lineHeight = 35;
   208→
   209→    // 헤더
   210→    const headerText = this.add.text(200, startY, '순위    이름      점수', {
   211→      fontSize: '16px',
   212→      color: '#ffff00',
   213→      fontStyle: 'bold',
