   218→
   219→    // 랭킹 데이터 표시
   220→    if (this.leaderboardData.length === 0) {
   221→      const noDataText = this.add.text(200, startY + 50, '아직 랭킹이 없습니다\n\n첫 번째 플레이어가 되어보세요!', {
