   238→      else if (entry.rank === 2) color = '#C0C0C0'; // 은색
   239→      else if (entry.rank === 3) color = '#CD7F32'; // 동색
   240→
   241→
   242→      const rankText = `${entry.rank}`.padEnd(8, ' ');
