   252→          color: color,
   253→          fontFamily: 'monospace',
   254→          stroke: '#000',
   255→          strokeThickness: 3
   256→        }
   257→      ).setOrigin(0.5);
   258→
   259→      this.leaderboardTexts.push(text);
   260→    });
   261→  }
   262→
   263→  private createBackButton() {
