        emojiText.setScale(1.1);
        title.setScale(1.05);
        description.setScale(1.05);
        infoBg.setScale(1.08);
        poopInfo.setScale(1.05);
        speedInfo.setScale(1.05);
      });

      element.on('pointerout', () => {
        button.setFillStyle(originalColor);
        button.setScale(1);
        shadow.setScale(1);
        innerBorder.setScale(1);
        emojiText.setScale(1);
        title.setScale(1);
        description.setScale(1);
        infoBg.setScale(1);
        poopInfo.setScale(1);
        speedInfo.setScale(1);
      });

      element.on('pointerdown', () => {
        this.startGame(difficultyConfig.difficulty);
      });
    });
  }

  private getDifficultyEmoji(difficulty: string): string {
    switch (difficulty) {
      case 'easy': return '😊';
      case 'normal': return '😐';
      case 'hard': return '😰';
      case 'extreme': return '💀';
      default: return '🎮';
    }
  }

  private getSpeedText(baseSpeed: number): string {
    if (baseSpeed <= 150) return '느림';
    if (baseSpeed <= 175) return '보통';
    if (baseSpeed <= 200) return '빠름';
    return '매우 빠름';
  }

  private lightenColor(color: number): number {
    // 색상을 밝게 만들기
    const r = Math.min(255, ((color >> 16) & 0xFF) + 30);
    const g = Math.min(255, ((color >> 8) & 0xFF) + 30);
    const b = Math.min(255, (color & 0xFF) + 30);
    return (r << 16) | (g << 8) | b;
  }

  private darkenColor(color: number): number {
    // 색상을 어둡게 만들기
    const r = Math.max(0, ((color >> 16) & 0xFF) - 40);
    const g = Math.max(0, ((color >> 8) & 0xFF) - 40);
    const b = Math.max(0, (color & 0xFF) - 40);
    return (r << 16) | (g << 8) | b;
  }

  private createPureButton(x: number, y: number) {
    const color = 0xeeeeee;
    const strokeColor = 0x888888;

    const shadow = this.add.rectangle(x + 3, y + 3, 170, 150, 0x000000, 0.5);

    const button = this.add.rectangle(x, y, 170, 150, color, 1);
    button.setStrokeStyle(4, strokeColor);

    const innerBorder = this.add.rectangle(x, y, 160, 140, color, 0)
      .setStrokeStyle(2, this.darkenColor(color));

    const emojiText = this.add.text(x, y - 48, '⚡', {
      fontSize: '32px'
    }).setOrigin(0.5);

    const title = this.add.text(x, y - 15, 'PHYSICAL', {
      fontSize: '20px',
      color: '#000',
      fontStyle: 'bold',
      stroke: '#fff',
      strokeThickness: 2
    }).setOrigin(0.5);

    const description = this.add.text(x, y + 10, '능력 없음 · 순수 실력', {
      fontSize: '11px',
      color: '#222',
      align: 'center'
    }).setOrigin(0.5);

    const infoBg = this.add.rectangle(x, y + 42, 150, 38, 0xffffff, 0.8);

    const modeInfo = this.add.text(x, y + 34, '🚫 캐릭터 능력 비활성', {
      fontSize: '11px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    const diffInfo = this.add.text(x, y + 50, '📊 EXTREME 기준 난이도', {
      fontSize: '11px',
      color: '#000',
      fontStyle: 'bold'
    }).setOrigin(0.5);

    button.setInteractive({ useHandCursor: true });
    const elements = [button, innerBorder, emojiText, title, description, infoBg, modeInfo, diffInfo];

    elements.forEach(element => {
      if (element !== button) {
        element.setInteractive({ useHandCursor: true });
      }

      element.on('pointerover', () => {
        button.setFillStyle(this.lightenColor(color));
        button.setScale(1.08);
        shadow.setScale(1.08);
        innerBorder.setScale(1.08);
        emojiText.setScale(1.1);
        title.setScale(1.05);
        description.setScale(1.05);
        infoBg.setScale(1.08);
        modeInfo.setScale(1.05);
        diffInfo.setScale(1.05);
      });

      element.on('pointerout', () => {
        button.setFillStyle(color);
        button.setScale(1);
        shadow.setScale(1);
        innerBorder.setScale(1);
        emojiText.setScale(1);
        title.setScale(1);
        description.setScale(1);
        infoBg.setScale(1);
        modeInfo.setScale(1);
        diffInfo.setScale(1);
      });

      element.on('pointerdown', () => {
        this.scene.start('GameScene', {
          gameMode: this.gameMode,
          difficulty: 'extreme',
          purePhysical: true
        });
      });
    });
  }

  private startGame(difficulty: Difficulty) {
    this.scene.start('GameScene', {
      gameMode: this.gameMode,
      difficulty: difficulty
    });
  }
}

