CREATE TABLE IF NOT EXISTS "public"."leaderboard" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "difficulty" "text" NOT NULL,
    "score" integer NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"(),
    "character_type" "text" DEFAULT 'chibi'::"text",
    CONSTRAINT "leaderboard_difficulty_check" CHECK (("difficulty" = ANY (ARRAY['easy'::"text", 'normal'::"text", 'hard'::"text", 'extreme'::"text"]))),
    CONSTRAINT "leaderboard_score_check" CHECK (("score" >= 0))
);


ALTER TABLE "public"."leaderboard" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."profiles" (
    "id" "uuid" NOT NULL,
    "initials" character(3),
    "toss_user_id" "text",
    "created_at" timestamp with time zone DEFAULT "now"()
);


ALTER TABLE "public"."profiles" OWNER TO "postgres";


