   273→  private getSpeedText(baseSpeed: number): string {
   274→    if (baseSpeed <= 150) return '느림';
   275→    if (baseSpeed <= 175) return '보통';
   276→    if (baseSpeed <= 200) return '빠름';
   277→    return '매우 빠름';
   278→  }
   279→
   280→  private lightenColor(color: number): number {
   281→    const r = Math.min(255, ((color >> 16) & 0xFF) + 30);
   282→    const g = Math.min(255, ((color >> 8) & 0xFF) + 30);
   283→    const b = Math.min(255, (color & 0xFF) + 30);
   284→    return (r << 16) | (g << 8) | b;
   285→  }
