      diamondPoop.body.velocity.y = fallSpeed;
    }

    // console.log(`다이아똥 생성! 점수: ${this.score}, 위치: (${x}, ${y}), depth: ${diamondPoop.depth}`);
  }

  private spawnTopazPoop() {
    if (this.gameOver) return;

